import { React, useState, useEffect, Fragment } from "react";
import axios from "axios";
import { trackPromise } from "react-promise-tracker";
import ShowSpinner from "./ShowSpinner";

const SelectType = props => {
 
  const { setDisplayAlert } = props;

  const { 
    userProfile, 
    leaveType, 
    setLeaveType, 
    year, 
    setYear, 
    currentRacf, 
    refreshPage, 
    convert2MMDDYY, 
    setLeaveList,
    refDetails,
    setRefDetails,
    convertToLocal,
    superUserMode 
  } = props;

  const [balance, setBalance] = useState("");
  const [currentEntitlement, setCurrentEntitlement] = useState("");
  const [yearAry, setYearAry] = useState([]);

  // ==================== Other Leave States ====================
  const [refList, setRefList] = useState([]);
  const [selectedRef, setSelectedRef] = useState("N/A");
  const [otherLeaveType, setOtherLeaveType] = useState("N/A");
  // const [entitledDays, setEntitledDay] = useState("N/A");
  const [periodStart, setPeriodStart] = useState("N/A");
  const [periodEnd, setPeriodEnd] = useState("N/A");

  // Load years and set defaults
  useEffect(() => {       
    if (userProfile.years) {      
      const year_tup = JSON.parse(userProfile.years);      
      const year_ary = year_tup['year'];    
      const num_of_years = Object.keys(year_ary).length;
      const year_max = Object.values(year_ary)[num_of_years - 1];        

      if (!year) setYear(year_max);
      if (!leaveType) setLeaveType('LVE01');

      const year_only_ary = [];
      for (let i = 0; i < num_of_years; i++) {
        year_only_ary.push({ 
          "year": Object.values(year_ary)[i], 
          "desc": year_tup['period'][i]  
        });
      }
      setYearAry(year_only_ary);    
    }
  }, [userProfile.years, setYear, setLeaveType]);

  // ==================== Load Other Leave Reference List ====================
  useEffect(() => {
    if (leaveType !== 'LVE15') return;

    trackPromise(
      axios({
        url: "/eleave/api/getAllSpecialRef",
        method: "POST",
        headers: { "Content-type": "application/json", api: "yes" },
        data: JSON.stringify({ 
          'racf': currentRacf, 
          'super_mode': superUserMode, 
          'localTime': convertToLocal(Date.now()) 
        })      
      })
      .then(response => response.data)
      .then(response => {     
        setRefList(response || []);
        setSelectedRef("N/A");
      })
      .catch(error => console.log(error)),
      "getRefList"
    );
  }, [leaveType, currentRacf, superUserMode, convertToLocal]);

  // ==================== Get Reference Details when selected ====================
  useEffect(() => {
    if (selectedRef === "N/A" || leaveType !== 'LVE15') return;

    trackPromise(
      axios({
        url: "/eleave/api/getRefDetails",
        method: "POST",
        headers: { "Content-type": "application/json", api: "yes" },
        data: JSON.stringify({ 'ref_no': selectedRef })      
      })
      .then(response => response.data)
      .then(response => {     
        const data = response[0];
        if (data) {
          setRefDetails(data);
          setOtherLeaveType(data.leave_name || "N/A");
          // setEntitledDay(data.entitled_days ? data.entitled_days.toFixed(1) : "N/A");
          setPeriodStart(convert2MMDDYY(data.period_start));
          setPeriodEnd(convert2MMDDYY(data.period_end));
        }
      })
      .catch(error => console.log(error)),
      "getRefDetails"
    );
  }, [selectedRef, leaveType, convert2MMDDYY, setRefDetails]);

  // ==================== Get Balance & Entitlement ====================
  useEffect(() => {
    if (!year || !leaveType) return;

    const yearEntitlement = userProfile.entitlement.filter(x => x.year === Number(year));

    if (yearEntitlement.length === 0) return;

    // Set Current Entitlement
    if (leaveType === 'LVE01') {
      const lastYearEntitlement = (Number(year) - 1).toString();
      const annualCarryForward = (yearEntitlement[0].carry_forward).toString();
      const thisYearEntitlement = (yearEntitlement[0].annual_entitlement).toString();
      
      const _currentEntitlement = `${annualCarryForward} (${lastYearEntitlement}) + ${thisYearEntitlement} (${year})`;
      setCurrentEntitlement(_currentEntitlement);
    } 
    else if (leaveType === 'LVE02') {
      const casualEntitlement = (yearEntitlement[0].casual_entitlement).toString();
      setCurrentEntitlement(`(${casualEntitlement}) ${year}`);
    }

    // Fetch leave balance
    trackPromise(
      axios({
        url: "/eleave/api/listleave",
        method: "POST",
        headers: { "Content-type": "application/json", api: "yes" },
        data: JSON.stringify({ "year": Number(year), "racf": currentRacf })
      })
      .then(response => response.data)
      .then(response => {
        const headerData = response['result'][0]["header"];

        const lve04 = headerData.find(item => item.leaveTypeId === 'LVE04');
        const lve05 = headerData.find(item => item.leaveTypeId === 'LVE05');

        const mergedSickLeave = {
          balance: (lve04?.balance || 0) + (lve05?.balance || 0),
          leaveType: 'TOTAL SICK LEAVE (Merged LVE04 & LVE05)',
          leaveTypeId: leaveType === 'LVE04' ? 'LVE04' : 'LVE05',
          pending: (lve04?.pending || 0) + (lve05?.pending || 0),
          taken: (lve04?.taken || 0) + (lve05?.taken || 0)
        };

        const consolidatedHeaderData = headerData
          .filter(item => item.leaveTypeId !== 'LVE04' && item.leaveTypeId !== 'LVE05')
          .concat((leaveType === 'LVE04' || leaveType === 'LVE05') ? mergedSickLeave : []);

        const balance_selected = consolidatedHeaderData.filter(x => x["leaveTypeId"] === leaveType);
        setBalance(balance_selected[0] || {});
      })
      .catch(error => console.log(error)),
      "typeOfLeave"
    );

    return () => setBalance({});
  }, [year, leaveType, userProfile, currentRacf, refreshPage]);

  // Handle Year Change
  const handleSelectYear = event => {
    const { value } = event.target;
    const yearEntitlement = userProfile.entitlement.filter(x => x.year === Number(value));

    if (yearEntitlement.length === 0) {
      setDisplayAlert({ 
        message: `Year ${value} is not available!`, 
        position: 1, 
        timeout: 3000, 
        color: "alert__red" 
      });
    }
    setYear(value);
  };

  // Handle Leave Type Change
  const handleSelectLeaveType = event => {
    const { value } = event.target;
    setLeaveList([]);
    setLeaveType(value);
    setSelectedRef("N/A");        // Reset reference when changing leave type
  };

  // Handle Reference Selection
  const handleSelectRef = event => {
    const { value } = event.target;
    setSelectedRef(value);
  };

  // Prevent loading error on page refresh
  try {
    if (!userProfile.staff?.name) {
      window.location = "/login";
    }
  } catch {
    window.location = "/login";
  }


  return (
    <Fragment>
      <div>
        <div>
          <div className="separator">Applicant Details</div>

          <div className="emp_grid">
            <div className="emp_area_a emp_grid_a">
              <div>Name:</div>
              <div>{userProfile.staff.name}</div>
            </div>
            <div className="emp_area_b emp_grid_b">
              <div>Position:</div>
              <div>{userProfile.staff.position}</div>
            </div>
            <div className="emp_area_c emp_grid_c">
              <div>Division/Department:</div>
              <div>{userProfile.staff.dept}</div>
            </div>
            <div className="emp_area_d emp_grid_d">
              <div>Date Joined:</div>
              <div>{convert2MMDDYY(userProfile.staff.date_join)}</div>
            </div>
          </div>

          <div className="separator">Select Leave Type</div>

          <div className="type_grid">
            {/* Select Leave Type */}
            <div className="type_area_a type_grid_a">
              <div>Select Leave Type:</div>
              <div>
                <select 
                  style={{ width: '30rem' }} 
                  onChange={handleSelectLeaveType} 
                  value={leaveType} 
                  className="clickable"
                >
                  <option value="LVE01">Annual Leave</option>
                  {(userProfile.staff.office === "DEL" || userProfile.staff.office === "FLR") && (
                    <option value="LVE02">Casual/ Festivities Leave</option>
                  )}
                  <option value="LVE03">Work From Home</option>
                  <option value="LVE04">Sick Leave - With Medical Certificate</option>
                  <option value="LVE05">Sick Leave - No Medical Certificate</option>
                  <option value="LVE06">No Pay Leave</option>
                  <option value="LVE15">Others</option>
                </select>
              </div>
            </div>

            {/* Summary Title */}
            <div className="type_area_b type_grid_b" style={{ borderBottom: "2px solid gray", marginLeft: 0, marginRight: 0 }}>
              <div>
                {leaveType === 'LVE15' && otherLeaveType !== "N/A" 
                  ? otherLeaveType 
                  : leaveType === 'LVE01' ? "Annual Leave Summary"
                  : leaveType === 'LVE02' ? "Casual/ Festivities Leave Summary"
                  : leaveType === 'LVE03' ? "Work From Home Summary"
                  : (leaveType === 'LVE04' || leaveType === 'LVE05') ? "Sick Leave Summary"
                  : leaveType === 'LVE06' ? "No Pay Summary"
                  : ""}
              </div>
            </div>

            {/* Leave Calendar Year OR Select Reference # */}
            <div className="type_area_c type_grid_c">
              <div>
                {leaveType === 'LVE15' ? "Select Reference #:" : "Leave Calendar Year:"}
              </div>
              <div>
                {leaveType !== "LVE15" ? (
                  <select 
                    style={{ width: '30rem' }} 
                    onChange={handleSelectYear} 
                    value={year} 
                    className="clickable"
                  >
                    {yearAry.map((x, index) => (
                      <option key={index} value={x.year}>
                        {x.desc}
                      </option>
                    ))}
                  </select>
                ) : (
                  <select 
                    style={{ width: '30rem' }} 
                    onChange={handleSelectRef} 
                    value={selectedRef} 
                    className="clickable"
                  >
                    <option value="N/A" disabled>Click to select your requested leave</option>
                    {refList.map((ref) => (
                      <option key={ref.ref_no} value={ref.ref_no}>
                        {ref.ref_no}
                      </option>
                    ))}
                  </select>
                )}
              </div>
            </div>

            {/* Entitled Days OR Allowed Period */}
            <div className="type_area_f type_grid_f">
              <div>
                {leaveType === 'LVE15' ? "Allowed Period:" : "No. of Days Entitled For The Period:"}
              </div>
              <div>
                {leaveType === 'LVE15' 
                  ? `${periodStart} - ${periodEnd}` 
                  : (leaveType === 'LVE01' || leaveType === 'LVE02') 
                    ? currentEntitlement 
                    : "N/A"
                }
              </div>
            </div>

            {/* Days Already Taken */}
            <div className="type_area_d type_grid_d">
              <div>No. of Days Already Taken (Approved + Pending):</div>
              {leaveType !== "LVE15" ? (
                <div>
                  {isNaN(balance?.taken + balance?.pending) 
                    ? "N/A" 
                    : `${balance.taken + balance.pending} (${balance.taken} + ${balance.pending})`
                  }
                </div>
              ) : <div>
                    {isNaN(refDetails?.approved_days + refDetails?.pending_days) 
                    ? "N/A" 
                    : `${refDetails.approved_days + refDetails.pending_days} (${refDetails.approved_days} + ${refDetails.pending_days})`
                  }
                </div>
              }
            </div>

            {/* Days Left */}
            <div className="type_area_e type_grid_e">
              <div>No. of Days Left:</div>
                <div>
                  {(() => {
                    if (leaveType === 'LVE01' || leaveType === 'LVE02') {
                      return balance?.balance ?? "N/A";
                    } 
                    else if (leaveType === 'LVE15') {
                      return refDetails?.days_left ?? "N/A";
                    } 
                    else {
                      return "N/A";
                    }
                  })()}
                </div>
            </div>
          </div>
        </div>
      </div>

      <ShowSpinner position={10} />
    </Fragment>
  );
};

export default SelectType;