import { React, Fragment, useState, useEffect, useRef } from "react";
import { trackPromise } from "react-promise-tracker";
import axios from "axios";
import ShowSpinner from "./ShowSpinner";

const CancelRequest = props => {

  // passed parameters
  const { userList, setDisplayAlert, convertToLocal, superUserMode, convert2MMDDYY, setRefDetails } = props;

  // Core State
  const [racf, setRACF] = useState("");
  const [refList, setRefList] = useState([]);
  const [selectedRef, setSelectedRef] = useState("");

  const [leaveType, setLeaveType] = useState("N/A");
  const [entitledDays, setEntitledDay] = useState("N/A");
  const [periodStart, setPeriodStart] = useState("N/A");
  const [periodEnd, setPeriodEnd] = useState("N/A");

  // Cancel flag to prevent getRefDetails from firing during/after cancellation
  const [isCanceling, setIsCanceling] = useState(false);

  // Searchable Dropdown States
  const [applicantSearch, setApplicantSearch] = useState("");
  const [showSuggestions, setShowSuggestions] = useState(false);
  const [highlightedIndex, setHighlightedIndex] = useState(-1);
  const dropdownRef = useRef(null);

  // 1. Filter Logic
  const filteredUsers = userList ? userList.filter(user => {
    const searchTerm = applicantSearch.toLowerCase();
    return (
      user.name.toLowerCase().includes(searchTerm) ||
      user.racf.toLowerCase().includes(searchTerm)
    );
  }).slice(0, 1000) : [];

  // 2. Auto-scroll Effect
  useEffect(() => {
    if (showSuggestions && highlightedIndex >= 0 && dropdownRef.current) {
      const items = dropdownRef.current.querySelectorAll('.suggestion-item');
      if (items[highlightedIndex]) {
        items[highlightedIndex].scrollIntoView({
          behavior: "smooth",
          block: "nearest"
        });
      }
    }
  }, [highlightedIndex, showSuggestions]);

  // 3. Selection Handlers
  const selectApplicant = (user) => {
    setRACF(user.racf.toUpperCase());
    setApplicantSearch(`${user.name} (${user.racf})`);
    setShowSuggestions(false);
    setHighlightedIndex(-1);
  };

  const handleApplicantSearch = (e) => {
    setApplicantSearch(e.target.value);
    setShowSuggestions(true);
    setHighlightedIndex(0);
    if (e.target.value === "") {
      setRACF("");
      setRefList([]);
    }
  };

  // 4. Keyboard Navigation Logic
  const handleKeyDown = (e) => {
    if (!showSuggestions || filteredUsers.length === 0) return;

    switch (e.key) {
      case "ArrowDown":
        e.preventDefault();
        setHighlightedIndex(prev => prev < filteredUsers.length - 1 ? prev + 1 : 0);
        break;
      case "ArrowUp":
        e.preventDefault();
        setHighlightedIndex(prev => prev > 0 ? prev - 1 : filteredUsers.length - 1);
        break;
      case "Enter":
        e.preventDefault();
        if (highlightedIndex >= 0 && highlightedIndex < filteredUsers.length) {
          selectApplicant(filteredUsers[highlightedIndex]);
        }
        break;
      case "Escape":
        setShowSuggestions(false);
        setHighlightedIndex(-1);
        break;
      default:
        break;
    }
  };

  function handleRefNo(event) {
    const { value } = event.target;
    setSelectedRef(value);
  }

  // Effect: Get Reference List when RACF is set
  useEffect(() => {
    if (!racf) return;
    trackPromise(
      axios({
        url: "/eleave/api/getAllSpecialRef",
        method: "POST",
        headers: { "Content-type": "application/json", api: "yes" },
        data: JSON.stringify({ 'racf': racf, 'super_mode': superUserMode, 'localTime': convertToLocal(Date.now()) })
      })
        .then(response => response.data)
        .then(response => {
          setRefList(response);
        }),
      "getRefListinCancel"
    );
  }, [racf, superUserMode, convertToLocal]);

  // Effect: Get Details when Ref No is selected (skipped during cancellation)
  useEffect(() => {
    if (!selectedRef || isCanceling) return;

    trackPromise(
      axios({
        url: "/eleave/api/getRefDetails",
        method: "POST",
        headers: { "Content-type": "application/json", api: "yes" },
        data: JSON.stringify({ 'ref_no': selectedRef })
      })
        .then(response => response.data)
        .then(response => {
          if (response[0]) {
            setRefDetails(response[0]);
            setLeaveType(response[0].leave_name);
            setEntitledDay(response[0].entitled_days.toFixed(1));
            setPeriodStart(convert2MMDDYY(response[0].period_start));
            setPeriodEnd(convert2MMDDYY(response[0].period_end));
          }
        }),
      "getRefDetails"
    );
  }, [selectedRef, convert2MMDDYY, setRefDetails, isCanceling]);

  const handleCancel = event => {
    if (!selectedRef) return;

    if (!window.confirm(`Are you sure you want to cancel ${selectedRef}?`)) {
      return null;
    }

    setIsCanceling(true);

    trackPromise(
      axios({
        url: "/eleave/api/cancelRequest",
        method: "POST",
        headers: { "Content-type": "application/json", api: "yes" },
        data: JSON.stringify({ 'ref_no': selectedRef, 'racf': racf })
      })
        .then(response => {
          // Trigger the success alert
          setDisplayAlert({ message: "Requisition cancelled successfully ", position: 4, timeout: 10000, color: "alert__green" });

          // Reset all local Leave Detail states back to "N/A"
          setLeaveType("N/A");
          setEntitledDay("N/A");
          setPeriodStart("N/A");
          setPeriodEnd("N/A");

          // Clear the dropdowns and search inputs
          setRACF("");
          setApplicantSearch("");
          setRefList([]);
          setSelectedRef("");

          // Clear the parent's refDetails state
          if (typeof setRefDetails === "function") {
            setRefDetails({});
          }

          setIsCanceling(false);
        })
        .catch(error => {
          const errMsg = error.response?.data?.error_message || "An error occurred";
          setDisplayAlert({ message: errMsg, position: 4, timeout: 10000, color: "alert__red" });
          setIsCanceling(false);
        }),
      "cancelOtherLeave"
    );
  };

  return (
    <Fragment>
      <ShowSpinner position={6} />

      <div>
        <div className="separator">Cancel Reference</div>

        <div className="cancelsp_type_grid">

          <div className="cancelsp_type_area_a cancelsp_type_grid_a">
            Applicant:
            <div style={{ position: "relative", display: "inline-block" }}>
              <input
                type="text"
                style={{ width: '30rem', height: "25px", padding: "0 5px" }}
                value={applicantSearch}
                onChange={handleApplicantSearch}
                onKeyDown={handleKeyDown}
                onFocus={() => setShowSuggestions(true)}
                onBlur={() => setTimeout(() => setShowSuggestions(false), 200)}
                placeholder="Search name or RACF..."
                autoComplete="off"
              />

              {showSuggestions && filteredUsers.length > 0 && (
                <div
                  ref={dropdownRef}
                  className="suggestions-dropdown"
                  style={{
                    position: "absolute",
                    top: "27px",
                    left: 0,
                    width: "30rem",
                    maxHeight: "200px",
                    overflowY: "auto",
                    backgroundColor: "white",
                    border: "1px solid #ccc",
                    zIndex: 1000,
                    boxShadow: "0 4px 8px rgba(0,0,0,0.1)"
                  }}
                >
                  {filteredUsers.map((user, index) => (
                    <div
                      key={index}
                      className={`suggestion-item ${index === highlightedIndex ? 'highlighted' : ''}`}
                      onClick={() => selectApplicant(user)}
                      onMouseDown={(e) => e.preventDefault()}
                      style={{
                        padding: "8px",
                        cursor: "pointer",
                        backgroundColor: index === highlightedIndex ? "#e0e0e0" : "white",
                        borderBottom: "1px solid #eee"
                      }}
                    >
                      {user.name} ({user.racf})
                    </div>
                  ))}
                </div>
              )}
            </div>
          </div>

          <div className="cancelsp_type_area_b cancelsp_type_grid_b">
            Approval #:
            <select style={{ width: '14rem', height: "25px" }} onChange={handleRefNo} id="specialLeave_select" className="clickable" value={selectedRef}>
              <option value="" disabled> - </option>
              {refList.map((ref) => (<option key={ref.ref_no} value={ref.ref_no}> {ref.ref_no}</option>))}
            </select>
          </div>

          <div className="cancelsp_type_area_c cancelsp_type_grid_c" style={{ borderBottom: "2px solid gray", marginLeft: 0, marginRight: 0 }}>
            <div><strong>Leave Details</strong></div>
          </div>

          <div className="cancelsp_type_area_d cancelsp_type_grid_d">
            Leave Type : {leaveType}
          </div>

          <div className="cancelsp_type_area_e cancelsp_type_grid_e">
            Entitled Days : {entitledDays}
          </div>

          <div className="cancelsp_type_area_f cancelsp_type_grid_f">
            Allowed Period: {periodStart} - {periodEnd}
          </div>

        </div>
        <button id="cancelsp_button" onClick={handleCancel}>
          Cancel
        </button>
      </div>
    </Fragment>
  );
};

export default CancelRequest;