import React, { useState, Fragment, useEffect } from "react";
import { trackPromise } from "react-promise-tracker";
import ShowAlert from "./components/ShowAlert";
import EnterRequest from "./components/EnterRequest";
import CancelRequest from "./components/CancelRequest";
import ShowSpinner from "./components/ShowSpinner";

const Requisition = props => {
  const { currentRacf, userProfile, superUserMode, convertToLocal, alert, setDisplayAlert, convert2MMDDYY } = props;

  const [office, setOfficeList] = useState([]);
  const [leaveType, setLeaveType] = useState([]);
  const [userList, setUserList] = useState([]);
  const [refDetails, setRefDetails] = useState([]);
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    const loadData = async () => {
      try {
        const fetchOffice = fetch("eleave/api/getoffice").then(res => res.json());
        const fetchLeave = fetch("eleave/api/getSpecialLeave").then(res => res.json());
        const fetchUsers = fetch("eleave/api/getUserList", { method: "POST" }).then(res => res.json());

        // trackPromise just for Spinner 
        await trackPromise(
          Promise.all([fetchOffice, fetchLeave, fetchUsers]),
          "prepareRequisitionForm"
        );

        const [officeRes, leaveRes, userRes] = await Promise.all([fetchOffice, fetchLeave, fetchUsers]);

        setOfficeList(officeRes);
        setLeaveType(leaveRes);

        let nUserList = userRes['userList'] || [];
        nUserList.sort((a, b) => (a.name < b.name ? -1 : 1));
        setUserList(nUserList);

      } catch (err) {
        console.error("Failed to load lists", err);
      } finally {
        setIsLoading(false);
      }
    };

    loadData();
  }, []);

  return (
    <Fragment>
      <div className="fade-in">
        <div className="subHeading"> Requisition (Special Leave) </div>

        {/* Loading Spinner  */}
        {isLoading ? (
          <ShowSpinner position={4} />
        ) : (
          <>
            <EnterRequest 
              userProfile={userProfile} 
              currentRacf={currentRacf} 
              office={office} 
              setOfficeList={setOfficeList} 
              leaveType={leaveType} 
              setLeaveType={setLeaveType}
              setDisplayAlert={setDisplayAlert} 
              userList={userList}
            />
            {(alert.position === 1 || alert.position === 4) && (
              <div className="flex-row">
                <div className="flex-large">
                  <ShowAlert alert={alert} />
                </div>
              </div>
            )}
            <CancelRequest 
              userProfile={userProfile} 
              currentRacf={currentRacf} 
              office={office} 
              setOfficeList={setOfficeList} 
              leaveType={leaveType} 
              setLeaveType={setLeaveType}
              setDisplayAlert={setDisplayAlert} 
              userList={userList} 
              superUserMode={superUserMode} 
              convertToLocal={convertToLocal} 
              convert2MMDDYY={convert2MMDDYY}
              refDetails={refDetails} 
              setRefDetails={setRefDetails}
            />
          </>
        )}
      </div>
    </Fragment>
  );
};

export default Requisition;